-- NSSMS-ARCH-013: governed ranking snapshots and entry-based awards; no scoring formula is encoded here.
CREATE TABLE rankings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),stage_id uuid NOT NULL REFERENCES competition_stages(id),occurrence_id uuid REFERENCES calendar_occurrences(id),event_id uuid NOT NULL REFERENCES events(id),category_id uuid NOT NULL REFERENCES categories(id),regulation_version_id uuid NOT NULL REFERENCES regulation_versions(id),ranking_type text NOT NULL CHECK(ranking_type IN ('EVENT','CATEGORY','STAGE')),calculation_version text NOT NULL,calculation_metadata jsonb,created_by_user_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','VALIDATED','PUBLISHED','ARCHIVED')),supersedes_ranking_id uuid REFERENCES rankings(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),archived_at timestamptz);
CREATE TABLE ranking_inputs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ranking_id uuid NOT NULL REFERENCES rankings(id),result_id uuid NOT NULL REFERENCES results(id),result_validation_id uuid NOT NULL REFERENCES result_validations(id),input_order integer,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(ranking_id,result_id));
CREATE TABLE ranking_rows (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ranking_id uuid NOT NULL REFERENCES rankings(id),competition_entry_id uuid NOT NULL REFERENCES competition_entries(id),position integer NOT NULL CHECK(position>0),points numeric,result_summary jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(ranking_id,competition_entry_id));
CREATE TABLE awards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ranking_id uuid REFERENCES rankings(id),competition_entry_id uuid NOT NULL REFERENCES competition_entries(id),award_type text NOT NULL CHECK(award_type IN ('MEDAL','TITLE','TROPHY','CERTIFICATE','OTHER')),label text,regulation_version_id uuid NOT NULL REFERENCES regulation_versions(id),status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','ISSUED','REVOKED','ARCHIVED')),issued_by_user_id uuid REFERENCES users(id),issued_at timestamptz,revoked_by_user_id uuid REFERENCES users(id),revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),archived_at timestamptz);
CREATE UNIQUE INDEX rankings_current_official_uk ON rankings(stage_id,event_id,category_id,ranking_type) WHERE status IN ('VALIDATED','PUBLISHED') AND supersedes_ranking_id IS NULL;
CREATE INDEX rankings_context_idx ON rankings(stage_id,event_id,category_id,status); CREATE INDEX ranking_inputs_result_idx ON ranking_inputs(result_id,result_validation_id); CREATE INDEX ranking_rows_position_idx ON ranking_rows(ranking_id,position); CREATE INDEX awards_entry_status_idx ON awards(competition_entry_id,status);
CREATE OR REPLACE FUNCTION nssms_rank_draft_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' AND NEW.status<>'DRAFT' THEN RAISE EXCEPTION 'new ranking snapshots must begin in DRAFT'; END IF; IF TG_OP='DELETE' AND OLD.status<>'DRAFT' THEN RAISE EXCEPTION 'official rankings cannot be deleted'; END IF; IF TG_OP='UPDATE' AND OLD.status IN ('VALIDATED','PUBLISHED','ARCHIVED') THEN RAISE EXCEPTION 'official ranking snapshots are immutable'; END IF; IF TG_OP='UPDATE' AND NEW.status='ARCHIVED' AND OLD.status<>'ARCHIVED' THEN IF NEW.archived_at IS NOT NULL THEN RAISE EXCEPTION 'ranking archive timestamp is database-controlled'; END IF; NEW.archived_at:=now(); END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END; $$;
CREATE OR REPLACE FUNCTION nssms_validate_ranking_input() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE r rankings%ROWTYPE; rid uuid; BEGIN rid:=CASE WHEN TG_OP='DELETE' THEN OLD.ranking_id ELSE NEW.ranking_id END; SELECT * INTO r FROM rankings WHERE id=rid; IF r.status<>'DRAFT' THEN RAISE EXCEPTION 'ranking inputs are frozen'; END IF; IF TG_OP<>'DELETE' AND NOT EXISTS(SELECT 1 FROM results x JOIN result_validations v ON v.id=NEW.result_validation_id WHERE x.id=NEW.result_id AND v.result_id=x.id AND v.decision='VALIDATED' AND x.governed_status='VALIDATED' AND x.stage_id=r.stage_id AND x.event_id=r.event_id AND x.category_id=r.category_id AND x.regulation_version_id=r.regulation_version_id AND NOT EXISTS(SELECT 1 FROM result_validations s WHERE s.supersedes_validation_id=v.id) AND v.revision_no=(SELECT COALESCE(MAX(revision_no),0) FROM result_revisions WHERE result_id=x.id)) THEN RAISE EXCEPTION 'ranking input must use current validated matching result'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END; $$;
CREATE OR REPLACE FUNCTION nssms_validate_ranking_row() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE r rankings%ROWTYPE; rid uuid; BEGIN rid:=CASE WHEN TG_OP='DELETE' THEN OLD.ranking_id ELSE NEW.ranking_id END; SELECT * INTO r FROM rankings WHERE id=rid; IF r.status<>'DRAFT' THEN RAISE EXCEPTION 'ranking rows are frozen'; END IF; IF TG_OP<>'DELETE' AND NOT EXISTS(SELECT 1 FROM competition_entries e WHERE e.id=NEW.competition_entry_id AND e.stage_id=r.stage_id AND e.category_id=r.category_id) THEN RAISE EXCEPTION 'ranking row entry must match ranking stage and category'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END; $$;
CREATE OR REPLACE FUNCTION nssms_award_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' AND NEW.status<>'DRAFT' THEN RAISE EXCEPTION 'new awards must begin in DRAFT'; END IF; IF TG_OP='DELETE' AND OLD.status<>'DRAFT' THEN RAISE EXCEPTION 'governed awards cannot be deleted'; END IF; IF TG_OP='UPDATE' AND OLD.status IN ('ISSUED','REVOKED','ARCHIVED') THEN RAISE EXCEPTION 'governed awards are immutable'; END IF; IF TG_OP='UPDATE' AND NEW.status='ISSUED' AND OLD.status='DRAFT' THEN IF NEW.issued_at IS NOT NULL THEN RAISE EXCEPTION 'award issuance timestamp is database-controlled'; END IF; NEW.issued_at:=now(); END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END; $$;
CREATE TRIGGER rankings_guard BEFORE INSERT OR UPDATE OR DELETE ON rankings FOR EACH ROW EXECUTE FUNCTION nssms_rank_draft_only(); CREATE TRIGGER rankings_updated BEFORE UPDATE ON rankings FOR EACH ROW EXECUTE FUNCTION set_updated_at(); CREATE TRIGGER ranking_inputs_guard BEFORE INSERT OR UPDATE OR DELETE ON ranking_inputs FOR EACH ROW EXECUTE FUNCTION nssms_validate_ranking_input(); CREATE TRIGGER ranking_rows_guard BEFORE INSERT OR UPDATE OR DELETE ON ranking_rows FOR EACH ROW EXECUTE FUNCTION nssms_validate_ranking_row(); CREATE TRIGGER awards_guard BEFORE INSERT OR UPDATE OR DELETE ON awards FOR EACH ROW EXECUTE FUNCTION nssms_award_guard(); CREATE TRIGGER awards_updated BEFORE UPDATE ON awards FOR EACH ROW EXECUTE FUNCTION set_updated_at();
